protocol Repository<Item> {                 // Item is a primary associated type
  associatedtype Item: Identifiable
  func fetch(id: Item.ID) async throws -> Item
  func save(_ item: Item) async throws
}

struct OrderAPI: Repository {
  func fetch(id: UUID) async throws -> Order { try await api.order(id) }
  func save(_ item: Order) async throws { try await api.put(item) }
}

// 1) Constrained existential — heterogeneous conformers, one Item type
let repos: [any Repository<Order>] = [OrderAPI(), OrderCache(), OrderMock()]

// 2) Generic holder — no boxing, fully specialized
struct OrderScreen<R: Repository> where R.Item == Order {
  let repo: R
}

// 3) Hand-rolled eraser — when you must forget the concrete type entirely
struct AnyRepository<Item: Identifiable>: Repository {
  private let _fetch: (Item.ID) async throws -> Item
  private let _save: (Item) async throws -> Void

  init<R: Repository>(_ wrapped: R) where R.Item == Item {
    _fetch = wrapped.fetch
    _save = wrapped.save
  }
  func fetch(id: Item.ID) async throws -> Item { try await _fetch(id) }
  func save(_ item: Item) async throws { try await _save(item) }
}

let injected = AnyRepository(OrderAPI())    // type is AnyRepository<Order>

// 4) Closed set of cases — no protocol needed
enum Source {
  case network(OrderAPI)
  case cache(OrderCache)
}

final class ImageLoader {
  private var handlers: [(UIImage) -> Void] = []

  // Runs before the function returns — nothing to annotate
  func withPlaceholder(_ body: (UIImage) -> Void) {
    body(.placeholder)
  }

  // Stored for later, so it escapes
  func onLoad(_ handler: @escaping (UIImage) -> Void) {
    handlers.append(handler)
  }

  // Async dispatch escapes too
  func load(_ url: URL, completion: @escaping @Sendable (UIImage?) -> Void) {
    URLSession.shared.dataTask(with: url) { data, _, _ in
      completion(data.flatMap(UIImage.init(data:)))
    }.resume()
  }
}

final class Screen {
  let loader = ImageLoader()
  var image: UIImage?

  func start() {
    // ✅ weak capture: the loader outlives this screen
    loader.onLoad { [weak self] img in self?.image = img }

    // ❌ loader.onLoad { self.image = $0 }  — screen and loader keep each other alive
  }
}

