struct Countdown: Sequence {
  let start: Int

  func makeIterator() -> Iterator { Iterator(current: start) }

  struct Iterator: IteratorProtocol {
    var current: Int
    mutating func next() -> Int? {
      guard current > 0 else { return nil }
      defer { current -= 1 }
      return current
    }
  }
}

for tick in Countdown(start: 3) { print(tick) }        // 3 2 1
print(Countdown(start: 5).filter { $0.isMultiple(of: 2) })   // [4, 2]

// Closure-based iterator over a paged API
func pages(from first: Int) -> AnySequence<Int> {
  var page = first
  return AnySequence(AnyIterator {
    defer { page += 1 }
    return page <= 100 ? page : nil
  })
}

// Infinite sequence — only usable lazily
let fibonacci = sequence(state: (0, 1)) { state -> Int? in
  defer { state = (state.1, state.0 + state.1) }
  return state.0
}
print(Array(fibonacci.prefix(8)))                      // [0,1,1,2,3,5,8,13]

// Eager: three passes, three arrays
let eager = (1...1_000).map { $0 * $0 }.filter { $0 % 3 == 0 }.prefix(2)

// Lazy: one pass, stops after two matches, no intermediate arrays
let lazyResult = (1...1_000).lazy
  .map { $0 * $0 }
  .filter { $0 % 3 == 0 }
  .prefix(2)
print(Array(lazyResult))                               // [9, 36]

protocol Validator {
  associatedtype Value
  func validate(_ value: Value) throws
}

struct NotEmpty: Validator {
  func validate(_ value: String) throws {
    if value.isEmpty { throw ValidationError.empty }
  }
}

struct MaxLength: Validator {
  let limit: Int
  func validate(_ value: String) throws {
    if value.count > limit { throw ValidationError.tooLong(limit) }
  }
}

// The pieces that enable the leading dot
extension Validator where Self == NotEmpty {
  static var notEmpty: Self { NotEmpty() }
}
extension Validator where Self == MaxLength {
  static func maxLength(_ n: Int) -> Self { MaxLength(limit: n) }
}

struct Field<V: Validator> where V.Value == String {
  let validator: V
  init(validator: V) { self.validator = validator }
}

// Call sites never name the concrete type
let name = Field(validator: .notEmpty)
let bio = Field(validator: .maxLength(280))

